from audit_utils import *

for tree,layer in [('fr_printed','French as printed'),('fr','French corrected')]:
 rel=f'sources/{tree}/fr/195.tex'
 def r(a,b,line,kind='reading',why='',count=1):
  replace(rel,a,b,layer,'195-374',line,'A.3–5','400-dpi full scan and three enlarged bands. '+why,kind,count=count)
 r(r'\emph{minimal}',r'\uline{minimal}','minimal-pair definition',why='The defined term is underlined.')
 r(r'\emph{domine}',r'\uline{domine}','domination definition',why='The defined term is underlined.')
 r("dit d'autre part qu'un", "dit d'autre part, qu'un",'domination definition punctuation',why='The print includes the comma after part.')
 s,_,_=page_text(rel,374)
 m=re.search(r'si \$\\xi\$ est minimal et\nsi \$F\$ est exact à gauche.*?\$v\$ est surjectif\.',s,re.S)
 if not m: raise ValueError('Expected two minimal-pair consequences')
 r(m.group(0),underline_prose(m.group(0)),'two minimal-pair consequences',why='The prose of both consequences is underlined, with mathematical symbols separately set.')
 r(r'\result{PROPOSITION}{3.1}',r'\result{PROPOSITION}{3, 1}','proposition number',why='Printed comma-numbered statement.')
 r(r'\item[(i)]',r'\item[i.]','condition i label',why='Printed roman label with a period.')
 r(r'\item[(ii)] tout',r'\item[ii.] Tout','condition ii label and initial',why='Printed roman label and capital Tout.')
 r('est dominé par un couple\nminimal.','est dominé par un couple \\uline{minimal}.','condition ii emphasis',why='Only minimal is underlined here.')
 r('est artinien\n(en prenant','est artinien, (en prenant','artinian explanation',why='Restore the comma before the parenthesis.')
 r(r'\emph{tout pro-objet de $\mathcal C$ est'+'\nstrict}',r'\uline{tout pro-objet de} $\mathcal C$ \uline{est strict}','corollary interpretation',why='The prose is underlined; the category letter retains its own underline.')
 r(r'\subsection*{4. Exemple : groupes du type galoisien, groupes pro-algébriques}',r'\subsection*{\normalfont 4. \uline{Exemple : groupes du type galoisien, groupes pro-algébriques}.}','section 4 heading',why='Roman underlined heading with a period.')
 r('proposition 3.1','proposition 3, 1','reference to the corollary',why='The printed reference uses a comma.')
 r('« groupes pro-algébriques »',r'\fquote{\uline{groupes pro-algébriques}}','Serre terminology',why='Ordinary double quotes and an underline on the enclosed term.')
 r('de Serre\n[4]','de SERRE [4]','author name',why='The name is printed in capitals.')
 r(r'\subsection*{5. Exemple : « variétés formelles »}',r'\subsection*{\normalfont 5. \uline{Exemple : \fquote{variétés formelles}}.}','section 5 heading',why='Roman underlined heading, ordinary double quotes and final period.')
 s,_,_=page_text(rel,374)
 r(r'\mathcal C',r'\text{\uwave{C}}','category letters',count=s.count(r'\mathcal C'),why='The category is an upright C with a wavy underline.')
 upright_page(rel,layer,'195-374')

event('195-3.1-minimal-pairs','targeted proof check','If two maps out of a minimal pair give the same element, left exactness lifts the element to their equalizer, a strict subobject, which must be the whole object. Thus the map is unique. If the target pair is minimal and av=bv, its element lifts to the equalizer of a,b, so a=b and v is an epimorphism. The printed surjectif is retained in this categorical sense; no underlying-set surjectivity is inferred for an abstract category.','195, p. 374, consequences preceding Proposition 3, 1')
event('195-3.1','independent re-proof','Assume a set of minimal pairs suffices. Finite products and condition (ii) give a minimal pair dominating any finite family; maps of minimal pairs are unique by the equalizer argument and are epimorphisms by minimality of the target. This forms a cofiltered system. Its associated functor maps onto F by domination. For injectivity, refine two representatives to a common minimal pair; equality of their F-elements and minimality force the two maps to coincide. Conversely, in a strict pro-presentation, the element represented by id of a stage is minimal: if it lifts through a strict monomorphism u, represent the lift at a later stage and refine the equality so that an epimorphic transition factors through u. Then u is both epic and a strict monomorphism, hence an isomorphism. Every element comes from a stage, proving (ii); left exactness was checked on page 373. The ordinary smallness/solution-set qualification is recorded separately rather than inserted into the source.','195, p. 374, Proposition 3, 1')
event('195-3.1-cor','targeted proof check','For an artinian object X, choose a minimal subobject through which a given element of F(X) factors. A further proper strict subobject carrying its chosen lift would contradict that minimality, so it gives a minimal pair dominating the original pair. Proposition 3, 1 then applies. Conversely every pro-representable functor is left exact by page 373. Thus all pro-objects in such a category are strict, within the same size convention.','195, p. 374, artinian argument and Corollary')
event('195-A4-profinite-groups','independent re-proof','An inverse limit of finite discrete groups is compact Hausdorff and totally disconnected. Replace a system by its strict image system; compactness gives surjective projections, and a continuous map to a finite discrete group factors through one finite stage because its open kernel contains finitely many coordinate kernels. Conversely a compact Hausdorff totally disconnected group has a basis of open normal subgroups: start with a clopen identity neighborhood, use compactness to obtain an open stabilizer inside it, and take the core of this finite-index subgroup. The canonical map to the inverse limit of finite quotients is injective by separation and surjective by compactness and the finite intersection property. The same factorization identifies morphisms and proves the asserted equivalence.','195, p. 374, first example in section 4')
event('195-A4-arbitrary-base','refuted, with refined statement 195-A4-noetherian-base','The assertion that the artinian corollary applies to all finite group schemes over an arbitrary base is too broad. Let R=F_2 plus a square-zero vector space with independent elements e_1,e_2,..., and S=Spec R. In the constant finite group G=(Z/2)_S, let H_n consist of the identity component S and the other component Spec(R/(e_1,...,e_n)). It is the kernel of the morphism G to alpha_2^n sending the nonidentity section to (e_1,...,e_n), hence a strict subobject in the category of finite S-group schemes. The H_n form a strictly descending chain. With a noetherian base, strict subgroups of finite group schemes are closed and the finite coordinate algebras are noetherian, so this obstruction disappears. The broad historical assertion is preserved in both layers, with the qualification reserved for the notes.','195, p. 374, Dans tous ces exemples after the arbitrary-base finite group-scheme example')
event('195-A4-proalgebraic-and-homotopy','carried as background without fault found','The announced use for absolute and relative fundamental, homotopy and homology groups is a programme statement, not a construction supplied on this page. The identification with the cited quasi-algebraic/pro-algebraic theory is carried as background; its precise hypotheses and source locator will be assessed in the notes phase. The opening definition of the finite artinian Lambda-algebras continues on page 375.','195, p. 374, remainder of section 4 and opening of section 5')
record_page('195',374,r'''Compared sources/fr_printed/fr/195.tex and sources/fr/fr/195.tex entry lines 259–312 with scan leaf 7 at 400 dpi, full page and all three enlarged bands. Read the primed and double-primed minimal-pair symbols, both maps and F-images, proposition and reference numbers, pi-one, and the three Lambdas at the foot.

Both layers restore the selective underlining, commas after part and artinien, roman item labels with capital Tout, comma-numbered 3, 1, roman underlined headings with their periods, ordinary double quotes, SERRE capitals, wavy C and upright mathematical letters. No mathematical difference between the two layers was introduced on this page. The tiny fleck after the final comma is treated as scan/ink noise rather than an additional punctuation mark.

Proved the minimal-pair consequences, both directions of Proposition 3, 1, the artinian corollary and the equivalence with profinite groups. Recorded the smallness convention explicitly in the check. The phrase surjectif has the categorical epimorphism interpretation here. The application to finite group schemes over an unrestricted base fails: a square-zero base with infinitely many independent generators yields a descending chain of strict subgroup kernels in the constant group of order two. This substantive qualification is reserved for the notes and leaves both historical text layers unchanged. The programme claims and cited quasi-algebraic theory remain identified background.''')
